import gurobipy as gp
from gurobipy import GRB
machines = []
tasks = []
cost = {}
records = [r for r in LEGACY_RECORDS if r['source'] == '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/AP_testing/AP1/cost_12x12.csv']
for rec in records:
    machine = rec['values']['Machine']
    if machine not in machines:
        machines.append(machine)
    for (task, val) in rec['values'].items():
        if task != 'Machine':
            if task not in tasks:
                tasks.append(task)
            cost[machine, task] = float(val)
for i in machines:
    for j in tasks:
        if (i, j) not in cost:
            raise ValueError(f'Missing cost for machine {i}, task {j}')
m = gp.Model('assignment')
x_vars = m.addVars(machines, tasks, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost[i, j] * x_vars[i, j] for i in machines for j in tasks)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for j in tasks)) == 1 for i in machines), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for i in machines)) == 1 for j in tasks), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')